// streaming-smoke is a self-contained verifier for the per-agent live
// streaming fix in `entire review`. It does NOT call any agent API.
//
// # What it proves
//
// The fix routes each agent's stdout through a pseudo-terminal so the
// child's isatty(stdout) returns true and its runtime (libc / Rust / Node)
// reverts to line-buffered flushing instead of block-buffering until exit.
// To exercise that mechanism without burning tokens, this binary spawns
// ITSELF as a child in "probe" mode — and the probe deliberately
// block-buffers stdout when stdout is a pipe.
//
// # Three ways to run
//
// 1) Default (timeline comparison, ~2s, non-interactive):
//
//		go run ./e2e/streaming-smoke
//
//	   Spawns one probe with UsePTY=false (the bug) then one with
//	   UsePTY=true (the fix), printing event timestamps side-by-side.
//	   Pass 1's events cluster at end; pass 2's stagger by ~150ms.
//
// 2) Real review TUI with the fix on (interactive, ~12s):
//
//		go run ./e2e/streaming-smoke --tui
//
//	   Boots the same Bubble Tea dashboard the real `entire review`
//	   multi-agent run uses, with two fake "agents" wired through
//	   ReviewerTemplate (UsePTY=true). Press Ctrl+O during the run to
//	   drill into one agent's event buffer — you should see the buffer
//	   grow while the agent is still working.
//
// 3) Real review TUI with the bug on (interactive, ~12s):
//
//		go run ./e2e/streaming-smoke --tui-buggy
//
//	   Same as --tui but with UsePTY=false. Use this to A/B against
//	   --tui: drill-in stays at "(0 events)" until the agent exits.
package main

import (
	"bufio"
	"context"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"os/exec"
	"strings"
	"time"

	"github.com/mattn/go-isatty"

	"github.com/entireio/cli/cmd/entire/cli/review"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
)

const probeFlag = "--probe"

func main() {
	// Self-spawn pattern: re-exec the same binary with --probe to act as
	// the fake "buffering agent". Lets the whole smoke test live in one
	// file the user can run with `go run ./e2e/streaming-smoke`.
	if len(os.Args) > 1 && os.Args[1] == probeFlag {
		runProbe(os.Args[2:])
		return
	}

	useTUI := flag.Bool("tui", false, "boot the real review TUI with UsePTY=true (the fix)")
	useTUIBuggy := flag.Bool("tui-buggy", false, "boot the real review TUI with UsePTY=false (the bug)")
	flag.Parse()

	var err error
	switch {
	case *useTUI:
		err = runTUI(true)
	case *useTUIBuggy:
		err = runTUI(false)
	default:
		err = runTimeline()
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "streaming-smoke:", err)
		os.Exit(1)
	}
}

// runProbe is the fake-agent side. When stdout is a pipe (not a TTY)
// it wraps stdout in a bufio.Writer with a libc-typical 64KB buffer so
// per-line writes accumulate until exit — the same pattern that causes
// real agents to "burst at the end". When stdout IS a TTY it writes
// directly so the natural per-line flushing happens.
//
// Args (parsed from the probe sub-command's argv):
//
//	--lines N    how many lines to emit (default 5)
//	--delay D    sleep between lines (default 150ms)
//	--label S    prefix for each line so two probes are distinguishable
func runProbe(args []string) {
	fs := flag.NewFlagSet("probe", flag.ExitOnError)
	lines := fs.Int("lines", 5, "number of lines")
	delay := fs.Duration("delay", 150*time.Millisecond, "sleep between lines")
	label := fs.String("label", "probe", "per-line label")
	_ = fs.Parse(args)

	if isatty.IsTerminal(os.Stdout.Fd()) {
		for i := 1; i <= *lines; i++ {
			fmt.Fprintf(os.Stdout, "%s line %d/%d\n", *label, i, *lines)
			time.Sleep(*delay)
		}
		return
	}

	// Pipe path: simulate libc/Rust/Node block buffering. All lines stay
	// in the buffer until Flush() at exit — even though the loop sleeps
	// between writes, the runner sees them as one burst.
	w := bufio.NewWriterSize(os.Stdout, 64*1024)
	for i := 1; i <= *lines; i++ {
		fmt.Fprintf(w, "%s line %d/%d\n", *label, i, *lines)
		time.Sleep(*delay)
	}
	_ = w.Flush()
}

// runTimeline spawns the probe twice — once without PTY (bug), once with
// PTY (fix) — and prints per-event timing for each pass.
func runTimeline() error {
	self, err := os.Executable()
	if err != nil {
		return fmt.Errorf("locate self: %w", err)
	}

	fmt.Println("streaming-smoke: spawning probe twice to compare buffering behaviour.")
	fmt.Println("look for events clustered at end (Pass 1) vs staggered (Pass 2).")
	fmt.Println()

	if err := timelinePass("Pass 1: UsePTY=false (simulates the bug)", self, false); err != nil {
		return err
	}
	fmt.Println()
	if err := timelinePass("Pass 2: UsePTY=true (the fix)", self, true); err != nil {
		return err
	}
	fmt.Println()
	fmt.Println("for an interactive demo: `go run ./e2e/streaming-smoke --tui`")
	return nil
}

func timelinePass(label, selfPath string, usePTY bool) error {
	tmpl := buildProbeReviewer("smoke-probe", selfPath, []string{"--lines", "5"}, usePTY)
	started := time.Now()
	proc, err := tmpl.Start(context.Background(), reviewtypes.RunConfig{})
	if err != nil {
		return fmt.Errorf("%s: start: %w", label, err)
	}

	fmt.Printf("=== %s ===\n", label)
	for ev := range proc.Events() {
		printEvent(time.Since(started), ev)
	}
	if err := proc.Wait(); err != nil {
		return fmt.Errorf("%s: wait: %w", label, err)
	}
	return nil
}

// runTUI boots the real review Bubble Tea dashboard with two fake probes
// so the user can press Ctrl+O during the run and see drill-in streaming
// (when usePTY=true) or batched-at-EOF behaviour (when usePTY=false).
func runTUI(usePTY bool) error {
	self, err := os.Executable()
	if err != nil {
		return fmt.Errorf("locate self: %w", err)
	}
	if !isatty.IsTerminal(os.Stdout.Fd()) {
		return errors.New("--tui requires a real terminal; rerun without --tui for a non-interactive demo")
	}

	// Two probes with different cadence so the dashboard rows visibly
	// diverge. ~12s total — long enough to comfortably hit Ctrl+O,
	// switch agents, and watch the buffer grow before the run ends.
	reviewers := []reviewtypes.AgentReviewer{
		buildProbeReviewer("fast-probe", self, []string{"--lines", "20", "--delay", "300ms", "--label", "fast"}, usePTY),
		buildProbeReviewer("slow-probe", self, []string{"--lines", "12", "--delay", "1s", "--label", "slow"}, usePTY),
	}

	mode := "UsePTY=true (the fix)"
	if !usePTY {
		mode = "UsePTY=false (the bug)"
	}
	fmt.Printf("streaming-smoke TUI demo (%s)\n", mode)
	fmt.Println("press Ctrl+O during the run to drill into an agent's event buffer.")
	fmt.Println("press Ctrl+C to cancel. press any key to dismiss after both finish.")
	fmt.Println()
	time.Sleep(800 * time.Millisecond) // let the user read before the TUI takes over

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	agentNames := []string{reviewers[0].Name(), reviewers[1].Name()}
	tui := review.NewTUISink(agentNames, cancel, os.Stdout, os.Stdin)
	tui.Start()

	sinks := []reviewtypes.Sink{tui}
	if _, err := review.RunMulti(ctx, reviewers, reviewtypes.RunConfig{}, sinks); err != nil {
		// Non-fatal: a probe exit error shouldn't drown the demo's main point.
		fmt.Fprintln(os.Stderr, "streaming-smoke: RunMulti returned:", err)
	}
	return nil
}

func buildProbeReviewer(name, selfPath string, probeArgs []string, usePTY bool) *reviewtypes.ReviewerTemplate {
	return &reviewtypes.ReviewerTemplate{
		AgentName: name,
		BuildCmd: func(ctx context.Context, _ reviewtypes.RunConfig) *exec.Cmd {
			args := append([]string{probeFlag}, probeArgs...)
			return exec.CommandContext(ctx, selfPath, args...)
		},
		Parser: lineParser,
		UsePTY: usePTY,
	}
}

func printEvent(elapsed time.Duration, ev reviewtypes.Event) {
	prefix := fmt.Sprintf("  + %4dms  ", elapsed.Milliseconds())
	switch e := ev.(type) {
	case reviewtypes.AssistantText:
		fmt.Printf("%sAssistantText  %q\n", prefix, e.Text)
	case reviewtypes.Started:
		fmt.Printf("%sStarted{}\n", prefix)
	case reviewtypes.Finished:
		fmt.Printf("%sFinished{Success:%v}\n", prefix, e.Success)
	default:
		fmt.Printf("%s%T\n", prefix, ev)
	}
}

func lineParser(r io.Reader) <-chan reviewtypes.Event {
	ch := make(chan reviewtypes.Event, 16)
	go func() {
		defer close(ch)
		ch <- reviewtypes.Started{}
		s := bufio.NewScanner(r)
		for s.Scan() {
			line := strings.TrimRight(s.Text(), "\r")
			if line == "" {
				continue
			}
			ch <- reviewtypes.AssistantText{Text: line}
		}
		if err := s.Err(); err != nil {
			ch <- reviewtypes.RunError{Err: err}
			ch <- reviewtypes.Finished{Success: false}
			return
		}
		ch <- reviewtypes.Finished{Success: true}
	}()
	return ch
}

